session_start(); require_once __DIR__ . '/../includes/auth.php'; require_once __DIR__ . '/../includes/consent.php'; requireRole(['consent_manager', 'admin']); expireConsentRequests($pdo); $requests = $pdo->query('SELECT cr.id, cr.purpose, cr.requested_data, cr.status, cr.requested_at, cr.expires_at, i.full_name, u.username AS requester FROM consent_requests cr JOIN patients p ON p.id = cr.patient_id JOIN demo_health_identities i ON i.id = p.health_identity_id JOIN users u ON u.id = cr.requested_by ORDER BY cr.requested_at DESC')->fetchAll(PDO::FETCH_ASSOC); $pageTitle = 'Consent Requests'; require __DIR__ . '/../includes/header.php';
?><div class="d-flex justify-content-between align-items-center mb-4"><div><p class="eyebrow">Privacy operations</p><h1 class="h2">Consent Requests</h1></div></div><div class="card border-0 shadow-sm"><div class="card-body"><div class="table-responsive"><table class="table"><thead><tr><th>Patient</th><th>Requester</th><th>Purpose</th><th>Data</th><th>Status</th><th>Expiry</th></tr></thead><tbody><?php foreach ($requests as $request): ?><tr><td><?= e($request['full_name']) ?></td><td><?= e($request['requester']) ?></td><td><?= e($request['purpose']) ?></td><td><?= e($request['requested_data']) ?></td><td><?= e($request['status']) ?></td><td><?= e($request['expires_at'] ?? 'No expiry') ?></td></tr><?php endforeach; ?><?php if (!$requests): ?><tr><td colspan="6" class="text-muted">No consent requests found.</td></tr><?php endif; ?></tbody></table></div></div></div><?php require __DIR__ . '/../includes/footer.php'; ?>